/bin/zsh -lc "cat > src/orchestration/chatOrchestrator.acceptance.test.ts <<'EOF'
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import type {ChatSession} from '../types/session.js';

describe('beforeSession failure', () => {
  // specs/hal-engine-config-hooks/spec.md#11
  it('reports and cleans up a beforeSession failure while preserving the rejection', async () => {
    const session: ChatSession = {
      sessionId: 's1',
      userId: 'u1',
      entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    const failure = new Error('allocation failed');
    const events: unknown[] = [];
    const orchestrator = createChatOrchestrator(
      createMockProvider(),
      new PromptBuilder({identity: 'You are a test assistant.'}),
      undefined,
      {
        hooks: {
          beforeSession: async received => {
            events.push(['beforeSession', received]);
            throw failure;
          },
          beforeUserInput: async (_received, message) => {
            events.push(['beforeUserInput']);
            return message;
          },
          onError: async (received, error) => void events.push(['onError', received, error]),
          afterSession: async received => void events.push(['afterSession', received]),
        },
      }
    );

    const rejection = await orchestrator.processMessage(session).then(
      () => 'resolved',
      (error: unknown) => error
    );

    expect({rejection, events}).toEqual({
      rejection: failure,
      events: [
        ['beforeSession', session],
        ['onError', session, failure],
        ['afterSession', session],
      ],
    });
  });
});
EOF
